normalized_names AS (
    SELECT DISTINCT TRIM(name) AS name
    FROM source_names
    WHERE TRIM(name) <> ''
),
existing_unique AS (
    SELECT DISTINCT LOWER(TRIM(name)) AS key
    FROM combined_bio_unique
),
existing_rename AS (
    SELECT DISTINCT LOWER(TRIM(token)) AS key
    FROM rename_token_global
    UNION
    SELECT DISTINCT LOWER(TRIM(token)) AS key
    FROM rename_token_global_custom
)
INSERT INTO rename_token_global (token)
SELECT n.name
FROM normalized_names n
LEFT JOIN existing_unique u ON u.key = LOWER(n.name)
LEFT JOIN existing_rename r ON r.key = LOWER(n.name)
WHERE u.key IS NULL
  AND r.key IS NULL
ON CONFLICT (token) DO NOTHING;
